from collections import defaultdict

# Find smallest cube that is sum of two positive cubes in two different ways
sums = defaultdict(list)

limit = 200  # search range for cube roots
for a in range(1, limit):
    for b in range(a+1, limit):
        s = a**3 + b**3
        sums[s].append((a, b))

# Check which sums are themselves cubes, and have 2+ representations
results = []
for s, pairs in sums.items():
    if len(pairs) >= 2:
        c = round(s ** (1/3))
        if c**3 == s:
            results.append((s, c, pairs))

results.sort()
for s, c, pairs in results[:10]:
    print(f'{c}^3 = {s} = {pairs}')
"

