// Check cubes one by one for being expressible as sum of two cubes in 2+ ways
function findCubeRoot(n) {
    let c = Math.round(n ** (1/3));
    if (c**3 === n) return c;
    // BigInt check for precision
    let bc = BigInt(Math.round(Number(n) ** (1/3)));
    if (bc**3n === BigInt(n)) return bc;
    // Try nearby
    for (let d = -2n; d <= 2n; d++) {
        let t = bc + d;
        if (t > 0n && t**3n === BigInt(n)) return t;
    }
    return null;
}

const maxBase = 10000;
for (let n = 1; n < maxBase; n++) {
    const cube = BigInt(n) ** 3n;
    const ways = [];
    const maxA = Math.cbrt(Number(cube)) | 0;
    for (let a = 1; a <= maxA; a++) {
        const a3 = BigInt(a) ** 3n;
        const b3 = cube - a3;
        if (b3 <= 0n) continue;
        // Check if b3 is a perfect cube
        let b = Number(b3) ** (1/3);
        let bi = Math.round(b);
        if (BigInt(bi) ** 3n === b3 && bi > a) {
            ways.push([a, bi]);
        }
    }
    if (ways.length >= 2) {
        console.log(n + '^3 = ' + cube + ' = ways:', JSON.stringify(ways));
        break;
    }
}
console.log('Done searching up to base', maxBase);
